<?php
declare(strict_types=1);
function shop_url(array $params=[]): string { return 'catalogo.php'.($params?'?'.http_build_query($params):''); }
function shop_text(string $name,int $max=200): string {
    $v=$_GET[$name]??''; return is_string($v)?mb_substr(trim($v),0,$max):'';
}
function shop_title(array $p): string { return str_starts_with($p['code'],'DEMO-')?preg_replace('/^\[DEMO\]\s*/u','',$p['title']):$p['title']; }
function shop_media(int $id,string $variant='web'): string { return 'imagen.php?'.http_build_query(['id'=>$id,'variant'=>$variant]+(!empty($GLOBALS['shopPreview'])?['preview'=>1]:[])); }
function shop_select(bool $preview=false): string {
    $source=$preview?'(SELECT id,code,slug,title,unit_type,component_count,availability,description,dating_label,year_from,year_to,dating_certainty,dimensions_label,condition_description,provenance_public,price_mode,price_amount,price_currency,published_at,publication_status FROM pieces WHERE deleted_at IS NULL)':'public_pieces';
    return 'SELECT p.*,c.image_id,(SELECT GROUP_CONCAT(cat.name ORDER BY cat.position SEPARATOR " · ") FROM piece_categories pc JOIN categories cat ON cat.id=pc.category_id WHERE pc.piece_id=p.id) AS category_names FROM '.$source.' p LEFT JOIN piece_cover c ON c.piece_id=p.id ';
}
function shop_categories(): array {
    return query('SELECT c.id,c.name,c.slug,COUNT(DISTINCT p.id) AS total FROM categories c JOIN piece_categories pc ON pc.category_id=c.id JOIN public_pieces p ON p.id=pc.piece_id GROUP BY c.id,c.name,c.slug,c.position ORDER BY c.position,c.name')->fetchAll();
}
function shop_card(array $p,?string $reason=null): void {
    ?><article class="object-card"><a class="object-image" href="<?=h(shop_url(['pieza'=>$p['slug']]))?>"><?php if($p['image_id']): ?><img loading="lazy" src="<?=h(shop_media((int)$p['image_id']))?>" alt="<?=h(shop_title($p))?>"><?php else: ?><span class="no-image">Imagen pendiente</span><?php endif ?><span class="image-arrow" aria-hidden="true">↗</span></a><div class="object-meta"><span><?=h($p['category_names'])?></span><?php if($p['availability']!=='available'): ?><span class="status status-<?=h($p['availability'])?>"><?=h(AVAILABILITY[$p['availability']])?></span><?php endif ?></div><h3><a href="<?=h(shop_url(['pieza'=>$p['slug']]))?>"><?=h(shop_title($p))?></a></h3><?php if($reason): ?><p class="connection-reason"><?=h($reason)?></p><?php elseif($p['dating_label']): ?><p class="object-date"><?=h($p['dating_label'])?></p><?php endif ?><?php if($p['price_mode']==='visible'): ?><p class="object-price"><?=h($p['price_currency'])?> <?=h(number_format((float)$p['price_amount'],2,',','.'))?></p><?php elseif($p['price_mode']==='on_request'&&$p['availability']==='available'): ?><p class="object-price">Precio a consultar</p><?php endif ?></article><?php
}
function shop_header(string $title,bool $demo,?array $piece=null,bool $home=false): void {
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Pródigo: antigüedades, arte y objetos para descubrir. Explorá el catálogo y mirá cada pieza de cerca."><title><?=h($title)?> · Pródigo</title><link rel="stylesheet" href="assets/catalogo.css?v=minimal4"><script src="assets/catalogo.js?v=minimal4" defer></script></head><body class="<?=$home?'minimal-home':'catalog-page'?>"><?php if(!$home): ?><header class="shop-header"><a class="wordmark" href="catalogo.php" aria-label="Pródigo · Inicio"><img src="assets/prodigo-logo.png" width="272" height="214" alt="Pródigo"></a><?php if($piece): ?><nav class="header-breadcrumbs" aria-label="Ubicación"><a href="<?=h(shop_url(['vista'=>'catalogo']))?>">Catálogo</a><span aria-hidden="true">/</span><span aria-current="page"><?=h(shop_title($piece))?></span></nav><?php endif ?><details class="shop-menu"><summary aria-label="Abrir o cerrar menú"><span aria-hidden="true">☰</span> Menú</summary><nav aria-label="Principal"><a href="catalogo.php">Inicio</a><a href="<?=h(shop_url(['vista'=>'catalogo']))?>">Catálogo</a><a href="<?=h(shop_url(['vista'=>'azar']))?>">Descubrir ↗</a><?php if($demo): ?><p class="demo-strip">Muestra de demostración · Objetos ficticios e ilustraciones de ejemplo</p><?php endif ?></nav></details></header><?php endif ?><main><?php
}
function shop_footer(): void {
    ?></main><footer class="shop-footer"><a class="footer-brand" href="catalogo.php">Pródigo</a><p>Antigüedades · Arte · Objetos coleccionables</p><a class="admin-entry" href="index.php?page=list">Gestión privada ↗</a></footer></body></html><?php
}
function shop_home(): void {
    $categories=query('SELECT id,name,slug FROM categories ORDER BY position,name')->fetchAll();
    $random=query(shop_select()."WHERE c.image_id IS NOT NULL AND EXISTS (SELECT 1 FROM image_variants iv WHERE iv.image_id=c.image_id AND iv.variant='web') ORDER BY RAND() LIMIT 1")->fetch();
    ?><section class="home-identity" aria-label="Pródigo"><img class="home-logo" src="assets/prodigo-logo.png" width="272" height="214" alt="Máquina de escribir Pródigo"><h1>Pródigo<span aria-hidden="true">.</span></h1></section>
    <div class="home-layout <?=$random?'has-feature':''?>"><nav class="home-navigation" aria-label="Explorar la colección"><a class="home-catalog" href="<?=h(shop_url(['vista'=>'catalogo']))?>"><span>Catálogo</span><span aria-hidden="true">↗</span></a><div class="home-materials" aria-label="Tipos de material"><?php foreach($categories as $i=>$c): ?><a class="material-tile material-color-<?=$i%10?>" href="<?=h(shop_url(['vista'=>'catalogo','categoria'=>$c['slug']]))?>"><span><?=h($c['name'])?></span><span aria-hidden="true">↗</span></a><?php endforeach ?></div><a class="home-surprise" href="<?=h(shop_url(['vista'=>'azar']))?>"><span>Sorprendeme</span><span aria-hidden="true">✳</span></a></nav><?php if($random): ?><a class="home-feature" href="<?=h(shop_url(['pieza'=>$random['slug']]))?>"><div class="home-feature-image"><img src="<?=h(shop_media((int)$random['image_id']))?>" alt="<?=h(shop_title($random))?>" fetchpriority="high"></div><div class="home-feature-caption"><span><?=h(shop_title($random))?></span><span aria-hidden="true">↗</span></div></a><?php endif ?></div><?php
}
function shop_listing(): void {
    $q=shop_text('q'); $category=shop_text('categoria',120); $state=shop_text('estado',30); $sort=shop_text('orden',30);
    $where=[]; $args=[];
    if($q!=='') { $where[]='(p.title LIKE ? OR p.description LIKE ? OR p.code LIKE ? OR p.dating_label LIKE ? OR EXISTS (SELECT 1 FROM piece_field_values fv WHERE fv.piece_id=p.id AND fv.value_text LIKE ?))'; for($i=0;$i<5;$i++) $args[]='%'.$q.'%'; }
    if($category!=='') { $where[]='EXISTS(SELECT 1 FROM piece_categories pc JOIN categories cat ON cat.id=pc.category_id WHERE pc.piece_id=p.id AND cat.slug=?)'; $args[]=$category; }
    if(isset(AVAILABILITY[$state])) { $where[]='p.availability=?'; $args[]=$state; }
    $clause=$where?' WHERE '.implode(' AND ',$where):'';
    $total=(int)query('SELECT COUNT(*) FROM public_pieces p'.$clause,$args)->fetchColumn();
    $page=max(1,min(100000,(int)shop_text('p',8))); $size=18; $pages=max(1,(int)ceil($total/$size)); $page=min($pages,$page); $offset=($page-1)*$size;
    $order=match($sort) {'titulo'=>'p.title,p.id','antiguas'=>'p.year_from IS NULL,p.year_from,p.id',default=>'p.id DESC'};
    $rows=query(shop_select().$clause.' ORDER BY '.$order." LIMIT $size OFFSET $offset",$args)->fetchAll();
    $categories=shop_categories(); $label='El catálogo'; foreach($categories as $cat) if($cat['slug']===$category) $label=$cat['name'];
    ?><section class="catalog-heading"><p class="kicker">La colección</p><h1><?=h($label)?></h1><p>Para mirar de cerca, para elegir, para volver.</p></section><div class="catalog-layout"><aside class="catalog-sidebar"><h2>Categorías</h2><nav aria-label="Categorías"><a class="<?=$category===''?'selected':''?>" href="<?=h(shop_url(['vista'=>'catalogo','q'=>$q,'estado'=>$state,'orden'=>$sort]))?>">Todas las piezas</a><?php foreach($categories as $cat): ?><a class="<?=$category===$cat['slug']?'selected':''?>" href="<?=h(shop_url(['vista'=>'catalogo','categoria'=>$cat['slug'],'q'=>$q,'estado'=>$state,'orden'=>$sort]))?>"><span><?=h($cat['name'])?></span><span><?=h($cat['total'])?></span></a><?php endforeach ?></nav></aside><section class="catalog-results" aria-label="Piezas"><form class="catalog-filters" method="get" action="catalogo.php"><input type="hidden" name="vista" value="catalogo"><input type="hidden" name="categoria" value="<?=h($category)?>"><label class="search-label"><span class="sr-only">Buscar piezas</span><input type="search" name="q" value="<?=h($q)?>" placeholder="Buscar una pieza, una época, una marca…"></label><label><span class="sr-only">Disponibilidad</span><select name="estado"><option value="">Todos los estados</option><?php foreach(AVAILABILITY as $key=>$text): ?><option value="<?=$key?>" <?=$state===$key?'selected':''?>><?=$text?></option><?php endforeach ?></select></label><label><span class="sr-only">Ordenar</span><select name="orden"><option value="recientes">Más recientes</option><option value="antiguas" <?=$sort==='antiguas'?'selected':''?>>Más antiguas</option><option value="titulo" <?=$sort==='titulo'?'selected':''?>>Por título</option></select></label><button type="submit">Buscar ↗</button></form><div class="result-summary"><span><?=$total?> <?=$total===1?'pieza':'piezas'?></span><?php if($q||$state||$category): ?><a href="<?=h(shop_url(['vista'=>'catalogo']))?>">Limpiar filtros</a><?php endif ?></div><div class="objects-grid catalog-grid"><?php foreach($rows as $p) shop_card($p); ?></div><?php if(!$rows): ?><div class="catalog-empty"><h2>No encontramos piezas con esos filtros.</h2><a class="text-link" href="<?=h(shop_url(['vista'=>'catalogo']))?>">Volver a todas las piezas ↗</a></div><?php endif ?><?php if($pages>1): ?><nav class="shop-pagination" aria-label="Páginas"><?php $params=['vista'=>'catalogo','categoria'=>$category,'q'=>$q,'estado'=>$state,'orden'=>$sort]; if($page>1): ?><a href="<?=h(shop_url($params+['p'=>$page-1]))?>">← Anterior</a><?php endif ?><span><?=$page?> / <?=$pages?></span><?php if($page<$pages): ?><a href="<?=h(shop_url($params+['p'=>$page+1]))?>">Siguiente →</a><?php endif ?></nav><?php endif ?></section></div><?php
}
function shop_related(array $piece): array {
    $out=[]; $ids=[$piece['id']];
    $manual=query(shop_select().' JOIN piece_relations r ON r.target_id=p.id WHERE r.source_id=? ORDER BY r.position,p.id LIMIT 4',[$piece['id']])->fetchAll();
    foreach($manual as $p) {
        if(in_array($p['id'],$ids)) continue;
        $reason=query('SELECT explanation FROM piece_relations WHERE source_id=? AND target_id=? ORDER BY position LIMIT 1',[$piece['id'],$p['id']])->fetchColumn();
        $p['reason']=$reason; $out[]=$p; $ids[]=$p['id'];
    }
    $candidates=query(shop_select().'WHERE p.id<>? ORDER BY p.id DESC LIMIT 120',[$piece['id']])->fetchAll();
    $catMap=[];
    foreach(query('SELECT pc.piece_id,pc.category_id FROM piece_categories pc JOIN public_pieces p ON p.id=pc.piece_id')->fetchAll() as $row) $catMap[$row['piece_id']][]=$row['category_id'];
    $ownCats=$catMap[$piece['id']]??[];
    foreach($candidates as &$p) {
        $cats=$catMap[$p['id']]??[];
        $same=(bool)array_intersect($ownCats,$cats); $near=$piece['year_from']!==null&&$p['year_from']!==null&&abs($piece['year_from']-$p['year_from'])<=15;
        $p['score']=($near?2:0)+($same?1:0);
        $p['reason']=$near&&!$same?'Otra categoría, una época cercana':($same?'Otra pieza de la misma categoría':'Otra mirada a la colección');
    } unset($p);
    usort($candidates,fn($a,$b)=>$b['score']<=>$a['score']);
    foreach($candidates as $p) { if(count($out)>=4) break; if(in_array($p['id'],$ids)) continue; $out[]=$p; $ids[]=$p['id']; }
    return $out;
}
function shop_gallery(array $images): void {
    ?><div class="item-gallery"><?php if($images): ?><button class="main-image" id="open-zoom" aria-label="Ampliar imagen"><img id="main-photo" src="<?=h(shop_media((int)$images[0]['id']))?>" alt="<?=h($images[0]['alt_text'])?>"><span>Ampliar ↗</span></button><p id="photo-caption" class="photo-caption"><?=h($images[0]['caption'])?></p><div class="photo-thumbs" role="group" aria-label="Imágenes de la pieza"><?php foreach($images as $i=>$image): ?><button class="photo-thumb <?=$i===0?'active':''?>" data-photo="<?=h(shop_media((int)$image['id']))?>" data-zoom="<?=h(shop_media((int)$image['id'],'zoom'))?>" data-alt="<?=h($image['alt_text'])?>" data-caption="<?=h($image['caption'])?>" aria-label="Ver imagen <?=$i+1?>" aria-pressed="<?=$i===0?'true':'false'?>"><img src="<?=h(shop_media((int)$image['id'],'thumbnail'))?>" alt="" loading="lazy"></button><?php endforeach ?></div><dialog id="zoom-dialog"><div class="zoom-toolbar"><span id="zoom-count">1 / <?=count($images)?></span><button id="zoom-scale" type="button">Acercar +</button><button id="close-zoom" type="button" aria-label="Cerrar imagen">Cerrar ×</button></div><div class="zoom-stage"><img id="zoom-photo" alt=""></div><div class="zoom-bottom"><button id="prev-photo" type="button" aria-label="Imagen anterior">←</button><p id="zoom-caption"></p><button id="next-photo" type="button" aria-label="Imagen siguiente">→</button></div></dialog><?php else: ?><div class="item-no-image">Imagen pendiente</div><?php endif ?></div><?php
}
function shop_details(array $p,array $fields,bool $wallpaper=false): void {
    ?><article class="item-info"><p class="kicker"><?=h($p['category_names'])?></p><?php if($wallpaper): ?><h2 class="detail-title">La pieza en detalle</h2><?php else: ?><h1><?=h(shop_title($p))?></h1><?php endif ?><div class="item-status"><span class="status status-<?=h($p['availability'])?>"><?=AVAILABILITY[$p['availability']]?></span><span class="reference"><?=h($p['code'])?></span></div><?php if($p['dating_label']): ?><p class="item-dating"><?=h($p['dating_label'])?><?=$p['dating_certainty']==='estimated'?' · Datación aproximada':''?></p><?php endif ?><?php if($p['price_mode']==='visible'): ?><p class="item-price"><?=h($p['price_currency'])?> <?=h(number_format((float)$p['price_amount'],2,',','.'))?></p><?php elseif($p['price_mode']==='on_request'&&$p['availability']==='available'): ?><p class="item-price">Precio a consultar</p><?php endif ?><p class="item-description"><?=h($p['description'])?></p><dl class="object-facts"><?php if($p['unit_type']==='set'): ?><dt>Unidad</dt><dd>Conjunto<?=$p['component_count']?' de '.h($p['component_count']).' componentes':''?></dd><?php endif ?><?php if($p['dimensions_label']): ?><dt>Medidas</dt><dd><?=h($p['dimensions_label'])?></dd><?php endif ?><?php foreach($fields as $field): ?><dt><?=h($field['label'])?></dt><dd><?=h($field['value_text'])?></dd><?php endforeach ?></dl><?php if($p['condition_description']): ?><details open><summary>Estado de conservación</summary><p><?=h($p['condition_description'])?></p></details><?php endif ?><?php if($p['provenance_public']): ?><details><summary>Procedencia</summary><p><?=h($p['provenance_public'])?></p></details><?php endif ?><?php
    $email=config()['contact_email']??''; $whatsapp=preg_replace('/\D/','',config()['contact_whatsapp']??'');
    $message='Hola, quisiera consultar por '.shop_title($p).' ('.$p['code'].').'; $contact='';
    if($whatsapp) $contact='https://wa.me/'.$whatsapp.'?text='.rawurlencode($message);
    elseif(filter_var($email,FILTER_VALIDATE_EMAIL)) $contact='mailto:'.$email.'?'.http_build_query(['subject'=>'Consulta '.$p['code'],'body'=>$message],'','&',PHP_QUERY_RFC3986);
    if($contact&&in_array($p['availability'],['available','reserved'],true)): ?><a class="solid-button contact-button" href="<?=h($contact)?>" <?=$whatsapp?'target="_blank" rel="noopener"':''?>>Consultar por esta pieza ↗</a><?php endif ?></article><?php
}
function shop_item(array $p): void {
    $images=query('SELECT i.id,i.alt_text,i.caption,i.role FROM images i LEFT JOIN piece_cover c ON c.image_id=i.id AND c.piece_id=i.piece_id WHERE i.piece_id=? AND EXISTS (SELECT 1 FROM image_variants v WHERE v.image_id=i.id AND v.variant="web") ORDER BY (c.image_id IS NOT NULL) DESC,i.position,i.id',[$p['id']])->fetchAll();
    $fields=query('SELECT f.label,v.value_text FROM piece_field_values v JOIN category_fields f ON f.category_id=v.category_id AND f.field_key=v.field_key WHERE v.piece_id=? ORDER BY f.category_id,f.position',[$p['id']])->fetchAll();
    $settings=presentation_get((int)$p['id']);
    $trial=shop_text('plantilla',20);
    if(!empty($GLOBALS['shopPreview']) && in_array($trial,['panels','wallpaper'],true)) $settings['template']=$trial;
    $wallpaper=$settings['template']==='wallpaper' && count($images)>0;
    ?><div class="piece-presentation <?=h(presentation_classes($settings))?>">
    <?php if($wallpaper): ?><section class="wallpaper-hero" aria-label="Presentación de la pieza"><img class="wallpaper-photo" src="<?=h(shop_media((int)$images[0]['id']))?>" alt="<?=h($images[0]['alt_text'])?>"><div class="wallpaper-shade" aria-hidden="true"></div><div class="wallpaper-copy"><p class="kicker"><?=h($p['category_names'])?></p><h1><?=h(shop_title($p))?></h1><div class="item-status"><span class="status"><?=AVAILABILITY[$p['availability']]?></span><span class="reference"><?=h($p['code'])?></span></div><?php if($p['dating_label']): ?><p class="wallpaper-dating"><?=h($p['dating_label'])?></p><?php endif ?><?php if($settings['lead']): ?><p class="wallpaper-lead"><?=h($settings['lead'])?></p><?php endif ?><div class="wallpaper-actions"><a href="#piece-detail">Ver ficha ↓</a><button type="button" data-open-gallery>Ampliar imagen ↗</button></div></div></section><?php endif ?>
    <section id="piece-detail" class="item-layout <?=$wallpaper?'wallpaper-details':'panels-details'?>"><?php shop_details($p,$fields,$wallpaper); shop_gallery($images); ?></section></div>
    <?php $related=shop_related($p); if($related): ?><section class="related-section"><div class="section-heading heading-row"><div><p class="kicker">Seguir mirando</p><h2>Otras piezas, otros encuentros.</h2></div><a class="text-link" href="<?=h(shop_url(['vista'=>'azar']))?>">Dejarlo al azar ↗</a></div><div class="objects-grid related-grid"><?php foreach($related as $other) shop_card($other,$other['reason']); ?></div></section><?php endif ?><?php
}
